import json,pathlib,hashlib,platform
root=pathlib.Path(__file__).resolve().parents[1]
a=json.loads((root/'docs/generated-command-reference-benchmark.json').read_text());b=json.loads((root/'docs/generated-command-native-benchmark.json').read_text())
assert len(a['results'])==len(b['results'])==6
rows=[]
for x,y in zip(a['results'],b['results']):
 assert (x['name'],x['seed'],x['commands'],x['timing']['samples'])==(y['name'],y['seed'],y['commands'],y['timing']['samples'])
 rows.append({'seed':x['seed'],'commands':x['commands'],'samples':x['timing']['samples'],'javascript_median_ms':x['timing']['median_us']/1000,'rust_median_ms':y['timing']['median_us']/1000,'javascript_p95_ms':x['timing']['p95_us']/1000,'rust_p95_ms':y['timing']['p95_us']/1000,'median_ratio':x['timing']['median_us']/y['timing']['median_us']})
report={'platform':platform.platform(),'reference_runtime':a.get('runtime'),'rust':'1.99.1, release, thin LTO','scope':'Normal simulation dispatch with temporal history on six generated floor1 Avatar runs, ten generated floors per run. Rendering, autosave, filesystem and startup excluded. No Windows-runtime or end-to-end FPS claim.','fixture_sha256':hashlib.sha256((root/'fixtures/generated-walks-v48.json').read_bytes()).hexdigest(),'rows':rows}
(root/'docs/generated-command-comparison.json').write_text(json.dumps(report,indent=2))
lines=['# Native simulation comparison','','## What was measured','',report['scope'],'','Both implementations replayed the same472 commands from identical source fixtures. Each seed ran two warmup traces and six measured repetitions. Rust checks final source-state parity before timing. Reference JavaScript ran in '+a.get('runtime','Node')+', not a browser renderer. No concurrent builds/tests ran during timing.','','| Seed | JS median ms | Rust median ms | Median ratio | JS p95 ms | Rust p95 ms |','|---|---:|---:|---:|---:|---:|']
for r in rows:lines.append(f"| {r['seed']} | {r['javascript_median_ms']:.3f} | {r['rust_median_ms']:.3f} | {r['median_ratio']:.2f}× | {r['javascript_p95_ms']:.3f} | {r['rust_p95_ms']:.3f} |")
lines+=['','Ratios are per-seed medians, not a claim that every mechanic, frame or platform runs this many times faster. These are initial-floor traces, not a deep-floor worst-case benchmark.','','## Architecture','', 'Typed Rust state and copy-on-write floor/actor blocks avoid repeatedly copying unchanged dungeon data into every temporal snapshot. Simulation randomness and iteration order match the frozen reference. Save/export still traverse full state, and native automatic persistence incurs filesystem I/O. These separate costs are not hidden inside the simulation result.','','## Reproduce','','Run tools/cargo.sh run --release -p corpse-core --example generated_commands_bench and tools/benchmark-generated-commands-reference.mjs in sequence on an otherwise quiet machine. The fixtures and raw JSON timing reports are included in the source archive.','', 'Fixture SHA256: '+report['fixture_sha256']]
(root/'docs/native-performance-report.md').write_text('\n'.join(lines)+'\n')
print(json.dumps({'minimum_median_ratio':min(r['median_ratio']for r in rows),'maximum_median_ratio':max(r['median_ratio']for r in rows)},indent=2))
